use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " A LRU cache using a statically-sized array for storage."] # [doc = ""] # [doc = " `LRUCache` uses a fixed-capacity array for storage. It provides `O(1)` insertion, and `O(n)`"] # [doc = " lookup."] # [doc = ""] # [doc = " All items are stored inline within the `LRUCache`, so it does not impose any heap allocation or"] # [doc = " indirection.  A linked list is used to record the cache order, so the items themselves do not"] # [doc = " need to be moved when the order changes.  (This is important for speed if the items are large.)"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use uluru::LRUCache;"] # [doc = ""] # [doc = " struct MyValue {"] # [doc = "     id: u32,"] # [doc = "     name: &'static str,"] # [doc = " }"] # [doc = ""] # [doc = " // A cache with a capacity of three."] # [doc = " type MyCache = LRUCache<MyValue, 3>;"] # [doc = ""] # [doc = " // Create an empty cache, then insert some items."] # [doc = " let mut cache = MyCache::default();"] # [doc = " cache.insert(MyValue { id: 1, name: \"Mercury\" });"] # [doc = " cache.insert(MyValue { id: 2, name: \"Venus\" });"] # [doc = " cache.insert(MyValue { id: 3, name: \"Earth\" });"] # [doc = ""] # [doc = " // Use the `find` method to retrieve an item from the cache."] # [doc = " // This also \"touches\" the item, marking it most-recently-used."] # [doc = " let item = cache.find(|x| x.id == 1);"] # [doc = " assert_eq!(item.unwrap().name, \"Mercury\");"] # [doc = ""] # [doc = " // If the cache is full, inserting a new item evicts the least-recently-used item:"] # [doc = " cache.insert(MyValue { id: 4, name: \"Mars\" });"] # [doc = " assert!(cache.find(|x| x.id == 2).is_none());"] # [doc = " ```"] # [derive (Debug , Clone)] pub struct LRUCache < T , const N : usize > { # [doc = " The most-recently-used entry is at index `head`. The entries form a linked list, linked to"] # [doc = " each other by indices within the `entries` array.  After an entry is added to the array,"] # [doc = " its index never changes, so these links are never invalidated."] entries : ArrayVec < Entry < T > , N > , # [doc = " Index of the first entry. If the cache is empty, ignore this field."] head : u16 , # [doc = " Index of the last entry. If the cache is empty, ignore this field."] tail : u16 , }